-- Create a base table and a materialized view in PostgreSQL
CREATE TABLE sales (sale_id INT, region VARCHAR(50), amount DECIMAL);

-- Materialized view storing pre-aggregated regional sales
CREATE MATERIALIZED VIEW mv_regional_sales AS
SELECT region, SUM(amount) AS total_sales
FROM sales
GROUP BY region;

-- Refresh the materialized view to sync with base table updates
REFRESH MATERIALIZED VIEW mv_regional_sales;

