-- Session 1:
BEGIN TRANSACTION;
UPDATE Accounts SET balance = balance - 100 WHERE id = 1; -- Holds lock on ID 1
-- Wait for Session 2 to release ID 2...
UPDATE Accounts SET balance = balance + 100 WHERE id = 2;

-- Session 2 (running concurrently):
BEGIN TRANSACTION;
UPDATE Accounts SET balance = balance + 50 WHERE id = 2; -- Holds lock on ID 2
-- Deadlock occurs here when Session 2 tries to update ID 1
UPDATE Accounts SET balance = balance - 50 WHERE id = 1;

-- Conceptual representation of ARIES Transaction and Dirty Page tables
CREATE TABLE aries_transaction_table (
    txn_id INT PRIMARY KEY,
    status VARCHAR(20), -- RUNNING, COMMITTED, ABORTED
    last_lsn INT
);

CREATE TABLE aries_dirty_page_table (
    page_id INT PRIMARY KEY,
    rec_lsn INT -- Oldest log record that dirtied the page without flushing
);

-- Example query during Analysis Phase to find the starting point for Redo
SELECT MIN(rec_lsn) AS redostart_lsn FROM aries_dirty_page_table;

