CREATE TYPE Person_t AS (
    id INT,
    name VARCHAR(50)
);

-- Employee specializes Person by adding salary
CREATE TYPE Employee_t UNDER Person_t (
    salary DECIMAL(10,2)
);

CREATE TABLE Persons OF Person_t;
CREATE TABLE Employees OF Employee_t UNDER Persons;

INSERT INTO Employees VALUES (ROW(1, 'Alice', 75000.00));
