-- Node A (Account DB) and Node B (Inventory DB)

BEGIN DISTRIBUTED TRANSACTION;

-- Update balance on Server A
UPDATE ServerA.BankDB.dbo.Accounts 
SET Balance = Balance - 500 
WHERE AccountID = 101;

-- Update inventory on Server B
UPDATE ServerB.InventoryDB.dbo.Stock 
SET Quantity = Quantity - 1 
WHERE ItemID = 55;

-- If both succeed without error, commit globally
COMMIT TRANSACTION;
-- If any error occurs, execute ROLLBACK TRANSACTION;

