def has_cycle(graph):
    visited = set()
    rec_stack = set()
    def dfs(node):
        visited.add(node)
        rec_stack.add(node)
        for neighbor in graph.get(node, []):
            if neighbor not in visited:
                if dfs(neighbor): return True
            elif neighbor in rec_stack:
                return True
        rec_stack.remove(node)
        return False
    for node in graph:
        if node not in visited:
            if dfs(node): return True
    return False

def hash_partition(key, num_partitions):
    return hash(key) % num_partitions

# Test partitioning for 4 nodes
data = ['North', 'South', 'East', 'West', 'Central']
partitions = {i: [] for i in range(4)}
for item in data:
    p = hash_partition(item, 4)
    partitions[p].append(item)
print(partitions)

def amdahls_law(p, s):
    # p = parallel fraction, s = number of processors
    return 1 / ((1 - p) + (p / s))

print(f'Speedup for p=0.9, s=8: {amdahls_law(0.9, 8):.2f}')

