-- Creating a composite type and evaluating value vs reference concepts in PostgreSQL
CREATE TYPE address_t AS (city VARCHAR(50), pin INT);

CREATE TABLE employees (
    id INT, 
    name VARCHAR(50),
    addr address_t
);

INSERT INTO employees VALUES (1, 'Alice',ROW('Gurugram', 122001));
INSERT INTO employees VALUES (2, 'Bob', ROW('Gurugram', 122001));

-- Value equality check on composite types
SELECT name, (addr = ROW('Gurugram', 122001)::address_t) AS matches_address 
FROM employees;

-- PostgreSQL example demonstrating arrays and JSONB columns
CREATE TABLE ai_models (
    model_id SERIAL PRIMARY KEY,
    model_name VARCHAR(100),
    tags TEXT[],
    metadata JSONB
);

INSERT INTO ai_models (model_name, tags, metadata)
VALUES ('BERT-Base', ARRAY['nlp', 'transformer'], '{"parameters": "110M", "framework": "PyTorch"}');

